<?php $title='Detalhes do módulo';$integrated=($connection['integration_status']??'')==='integrado'; ?>
<section class="page-head"><div><h1><?=e($project['name'])?></h1><p><?=e($project['description'])?></p></div><div><?php if($integrated):?><form method="post" action="<?=e(base_url('projetos/'.$project['id'].'/administrar'))?>"><?=csrf_field()?><button class="btn primary" type="submit">Administrar</button></form><?php endif;?></div></section>
<div class="detail-grid"><section class="panel"><h2>Identidade do módulo</h2><dl><dt>Nome</dt><dd><?=e($project['name'])?></dd><dt>Código</dt><dd><code><?=e($connection['module_code']??$project['code'])?></code></dd><dt>UUID</dt><dd><code><?=e($connection['module_instance_id']??'Não anexado')?></code></dd><dt>Slug</dt><dd><code><?=e($connection['module_slug']??'Não informado')?></code></dd><dt>URL</dt><dd><?=e($project['url']?:'Não configurada')?></dd><dt>Versão</dt><dd><?=e($project['version'])?></dd><dt>API version</dt><dd><?=e($connection['api_version']??'Não informada')?></dd></dl></section>
<section class="panel"><h2>Estado</h2><?php if(!$connection):?><div class="empty">Módulo não anexado.</div><?php else:?><dl><dt>Anexação</dt><dd><?=e(project_connection_status_label($connection['connection_status']))?></dd><dt>Integração</dt><dd><strong><?=$integrated?'Integrado':'Não integrado'?></strong></dd><dt>Health</dt><dd><?=e(($connection['health']['level']??'').' — '.($connection['health']['summary']??''))?></dd><dt>Compatibilidade</dt><dd><code><?=e(json_encode($connection['compatibility'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></code></dd><dt>Capabilities</dt><dd><code><?=e(json_encode($connection['capabilities'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></code></dd><dt>Última comunicação</dt><dd><?=$connection['last_communication_at']?e(date('d/m/Y H:i',strtotime($connection['last_communication_at']))):'Ainda não realizada'?></dd></dl><?php endif;?></section></div>
<section class="panel"><h2>Clientes com acesso</h2><?php if(!$clients):?><div class="empty">Nenhum cliente vinculado.</div><?php else:?><div class="project-list"><?php foreach($clients as$c):?><a href="<?=e(base_url('clientes/'.$c['id']))?>"><b><?=e($c['name'])?></b><small><?=e($c['identifier'])?></small></a><?php endforeach;?></div><?php endif;?></section>
<section class="panel"><h2>Atividade recente</h2><?php if(!$activities):?><div class="empty">Nenhuma atividade recente.</div><?php else:?><div class="timeline"><?php foreach($activities as$activity):?><div><span class="dot"></span><p><b><?=e($activity['user_name']??'Sistema')?></b> — <?=e($activity['description'])?><small><?=e(date('d/m/Y H:i',strtotime($activity['created_at'])))?></small></p></div><?php endforeach;?></div><?php endif;?></section>
